<template>
    <div>
        <div id="carouselExampleCaptions" class="carousel slide">
            <div class="carousel-indicators">
                <button type="button" data-bs-target="#carouselExampleCaptions" data-bs-slide-to="0" class="active" aria-current="true" aria-label="Slide 1"></button>
                <button v-for="(film,index) in films.slice(1)" type="button" data-bs-target="#carouselExampleCaptions" :data-bs-slide-to="index+1" :aria-label="'Slide' + (index+2) " :key="film.id"></button>
            </div>
            <div class="carousel-inner">
                <div v-for="(film, index) in films" :key="film.id" :class="['carousel-item', { active: index===0 }]">
                                                                        <!-- [ ]用來動態綁定多個類別。如果陣列中的某些條件評估為 false，Vue會自動忽略該類別，因此不會在最終的class屬性中出現。 使用 ['靜態類別', {條件類別: 條件}] 是Vue的推薦寫法，讓程式碼更直觀、易維護。-->
                    <!-- <a :href="'http://localhost:8080/movie/'+ film.id "> -->
                    <a :href="'#/movie/' + film.id">
                        <img :src="film.src" class="movieImg d-block w-100" :alt="film.alt">
                        <div class="carousel-caption d-none d-md-block">
                            <h5>{{ film.chineseTitle }}</h5>
                            <p>片長: {{ film.about.time }}</p>
                        </div>
                    </a>
                </div>
            </div>
            <button class="carousel-control-prev" type="button" data-bs-target="#carouselExampleCaptions" data-bs-slide="prev">
                <span class="carousel-control-prev-icon" aria-hidden="true"></span>
                <span class="visually-hidden">Previous</span>
            </button>
            <button class="carousel-control-next" type="button" data-bs-target="#carouselExampleCaptions" data-bs-slide="next">
                <span class="carousel-control-next-icon" aria-hidden="true"></span>
                <span class="visually-hidden">Next</span>
            </button>
        </div>
        <div class="quickBook container">
            <div class="quickBookDiv">
                <h4 class="quickBookH4">快速訂票</h4>
                <div class="bookMovie container">
                    <h5>電影</h5>
                    <select class="form-select selectMovie" v-model="homeSelectMovie" @change="handleMovieChange(homeSelectMovie)" aria-label="Default select example">
                        <option selected disabled value="">請選擇影片</option>
                        <option v-for="film in films" :value="film.chineseTitle" :key="film.id">{{ film.chineseTitle }}</option>
                    </select>
                </div>
                <div class="bookDate container">      
                    <h5>日期</h5>
                    <select class="form-select selectDate" v-model="homeSelectDate" @change="handleDateChange(homeSelectDate)" aria-label="Default select example">
                        <option selected disabled value="">請選擇日期</option>
                        <option v-for="date in Object.keys(avaliableDates)" :value="date" :key="date">{{ date }}</option>
                    </select>
                </div>
                <div class="bookSession container">       
                    <h5>場次</h5>
                    <select class="form-select selectSession" v-model="homeSelectSession" @change="handleSessionChange(homeSelectSession)" aria-label="Default select example">
                        <option selected disabled value="">請選擇場次</option>
                        <option v-for="session in avaliableSessions" :value="session" :key="session">{{ session }}</option>
                    </select>
                </div>
                <div class="btnDiv container">
                    <button type="button" @click="toBookTicketPage" class="btn btn-dark bookTicketBtn">訂票</button>
                    <router-link :to="'seatview'" class="btn btn-dark seatBtn seatBtnRouter" @click="checkCinema">查看座位</router-link>
                </div>
            </div>
            <router-view class="container seatTable"></router-view>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';

export default {
    name:"HomePage",
    data(){
        return{
            homeSelectMovie: "",
            homeSelectDate: "",
            homeSelectSession: "",
            homeSelectResult:[],
        }
    },
    computed: {
        ...mapState([
            "films",
            "selectMovie",
            "avaliableDates",
            "selectDate",
            "avaliableSessions",
            "selectSession",
        ])
    },
    methods: {
        /* 將使用者所選的電影，儲存至vuex的state.selectMovie，以便後續生成日期 */
        handleMovieChange(userSelectMovie){
            this.$store.commit("updateMovie", userSelectMovie);         
            this.$store.commit("updateDates", userSelectMovie);
        },

        /* 將使用者所選的日期，儲存至vuex的state.selectMovie，以便後續生成場次 */
        handleDateChange(userSelectDate){
            this.$store.commit("updateSessions", userSelectDate);
        },

        /* 將使用者所選的場次，儲存至vuex的state.selectSession*/
        handleSessionChange(userSelectSession){
            this.$store.commit("checkSession", userSelectSession);      
        },

        /* 若使用者電影、日期、場次等項目皆有選擇，則跳轉至訂票頁面。否則跳出提示訊息。 */
        toBookTicketPage(){
            if(this.homeSelectMovie && this.homeSelectDate && this.homeSelectSession){
                this.$router.push("/bookTicket");               /* 在hash模式下，網址會變成 http://localhost:8080/#/bookTicket */
            }else{
                alert("請確認電影、日期、場次皆已選擇，謝謝");
            }
        },

        /* 確認使用者電影、日期、場次皆已選擇。若都有選擇，則根據使用者所選的電影，確認其所在的廳院，以及該廳院的資料。若有尚未選擇的項目，則跳出提示訊息。  */
        checkCinema(){
            if(this.homeSelectMovie && this.homeSelectDate && this.homeSelectSession){
                this.cinema = this.films.find((film)=> film.chineseTitle === this.homeSelectMovie)?.cinema || ""             /*  這個不是三元運算子，而是『可選鏈 ?.』 能夠安全地存取物件屬性，避免 undefined 或 null 所引發的錯誤。『可選鏈 ?.』精常與 || 一起搭配使用，以提供預設值。*/
                switch(this.cinema){
                    case "第一廳":
                        this.cinemaSeatNum = 48
                        this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I"];
                        break;
                    case "第二廳":
                        this.cinemaSeatNum = 144;
                        this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L","M"];
                        break;
                    case "第三廳":
                    case "第四廳":
                        this.cinemaSeatNum = 120;
                        this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K"];
                        break;
                    case "第五廳":
                    case "第六廳": 
                    case "第七廳":
                        this.cinemaSeatNum = 84;
                        this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H"];
                        break;
                    default:
                    this.cinemaSeatNum = 0;
                        this.rowData = [];
                }
            }else{
                alert("請確認電影、日期、場次皆已選擇，謝謝");
            }
        },  
    }
}
</script>

<style scoped>
.movieImg{
    width: 100vw;
    height: 70vh;
}
.carousel-control-prev-icon, .carousel-control-next-icon{
    background-color: rgba(0, 0, 0, 0.212);
}
.quickBook{
    margin: 30px auto;
    display: flex;
}
.quickBookDiv{
    background-color: rgb(232,232,220);
    border-radius: 5px;
    padding: 0px 0px 10px;
    max-width: 380px;
    margin-right: 30px;
}
.quickBookH4{
    width: 100%;
    height: 48px;
    padding: 10px 10px 10px 30px;
    background-color:rgb(187,187,185);
    border-radius: 5px;
    font-weight: bold;
    text-align: left;
}
.quickBookDiv h5{
    margin: 5px 20px;
    padding: 10px 10px 0px;
}
.quickBookDiv select{
    width: 300px;
    height: 40px;
    margin: 0px 20px;
}
.btnDiv{
    margin: 15px 0px;
    text-align: center;
}
.btn{
    margin: 0px 5px;
}
.seatBtnRouter{
    color: white;
    text-decoration: none;
}
@media screen and (max-width: 960px){
    .quickBook{
        display: block;
        margin: 30px auto;
    }
    .quickBookDiv{
        margin: auto;
    }
    .seatTable{
        margin: 30px auto;
    }
    .movieImg{
        width: 100vw;
        height: 40vh;
    }
}
</style>