const localStore = new VuexPersistence({    /* 定義狀態想要存放的位置、需要存放的屬性 */
  storage: window.localStorage,
  reducer: state => ({
    seatStatus: state.seatStatus,
    orderConfirmed: state.orderConfirmed,
  })
});

const localStorageState = JSON.parse(localStorage.getItem("vuex")) || {};   /* 在createWebHistory()模式中，vuexPersist是正常的。但改為createWebHashHistory()模式保險起見就需要手動存取，避免錯誤。*/
                                                                            /* 從localStorage中讀取seatStatus和orderConfirmed */
export const store = createStore({
  state: {
    films,                        /* 電影資訊總覽 */
    foods,                        /* 餐飲資訊總覽 */
    selectMovie: "",              /* 使用者選擇的電影 */
    avaliableDates: {},           /* 可以選擇的日期  */
    selectDate: "",               /* 使用者選擇的日期 */
    avaliableSessions: [],        /* 可以選擇的場次 */
    selectSession: "",            /* 使用者選擇的場次 */
    regularTicketNum: 0,          /* 全票數量 */
    concessionTicketNum: 0,       /* 優待票數量 */
    totalTicketNum: 0,            /* 總票數 */
    chosenSeat: [],               /* 選擇的座位 */
    foodOrder: [],                /* 加購的餐飲 */
    totalPrice: 0,                /* 購物車總額 */
    payOnlineTemporaryOrder: [],  /* 暫存的訂單 */
    seatStatus: localStorageState.seatStatus || seatStatus,        /* 目前各場次的座位狀態(若localStorage中有資料就採用該筆資料，否則為預設的seatStatus資料) */
    orderConfirmed: localStorageState.orderConfirmed || [],       /* 確認的訂單(若localStorage中有資料就採用該筆資料，否則為空陣列) */
  },

  mutations: {
    
    /* 儲存使用者所選的電影 */
    updateMovie(state, userSelectMovie){
      state.selectMovie = userSelectMovie;                                                              
    },

    /* 根據使用者所選的電影，並生成可選的日期 */
    updateDates(state, userSelectMovie){
      const movie = state.films.find((movieDetail) => movieDetail.chineseTitle === userSelectMovie);      /* 透過find，比對電影總資料，找出使用者選擇的該片名的資料，並儲存到movie中，以便後續選擇該電影的日期與場次 */
      if (movie){                                                                                         /* 如果有找到對應的片名資料，就將該片名的日期與場次資料儲存到state.avaliableDates中。否則state.avaliableDates就會是一個空物件{} */
          state.avaliableDates = movie.dateSessions;                                      
        } else{
          state.avaliableDates = {};
        }
        state.selectDate = "";                                                                /* 當使用者重新選擇電影後，日期與場次的欄位應回到預設值(空字串或空陣列)，也就是尚未選擇的狀態 */
        state.avaliableSessions = [];
        state.selectSession = "";
    },

    /* 根據使用者所選的電影、日期，並生成可選的場次時間 */
    updateSessions(state, userSelectDate) {
      state.selectDate = userSelectDate;                                                     
      if (state.avaliableDates[userSelectDate]){                                             /* 使用者從可選的日期中(state.avaliableDates)選擇了某日期 */
        state.avaliableSessions = state.avaliableDates[userSelectDate];                     /* 將該日期有的場次資料儲存到state.avaliableSessions中，否則state.avaliableSessions就會是一個空陣列[] */                        
      } else{
        state.avaliableSessions = [];                     
      }                                                                                   /* state.avaliableDates[selectDate]這邊使用[]，而不是state.avaliableDates.selectDate的原因是因為selectDate是變數，不是avaliableDates內的直接屬性名稱。動態訪問物件屬性: 當屬性名稱是動態生成或存於變數中時，無法使用點語法，只能用中括號語法。 */
      
      state.selectSession= "";                                                       /* 當使用者重新選擇日期後，場次的欄位應回到預設值(空陣列) */
    },

    /* 儲存使用者所選的場次 */
    checkSession(state, userSelectSession){                                           
      state.selectSession = userSelectSession;                        
    },

    /* 儲存使用者所選的全票數量 */
    updateRegularTicketNum(state, userSelectRegularNum){
      state.regularTicketNum = userSelectRegularNum;
    },

    /* 儲存使用者所選的優待票數量 */
    updateConcessionTicketNum(state, userSelectConcessionNum){    
      state.concessionTicketNum = userSelectConcessionNum;
    },

    /* 儲存使用者所選的全部票券數量 */
    updateTotalTicketNum(state, userSelectTicketNum){
      state.totalTicketNum = userSelectTicketNum;
    },

    /* 更新與儲存使用者所選擇的座位 */
    updateChosenSeat(state, userChosenSeat){                              
      state.chosenSeat = userChosenSeat;
    },

    /* 將加購餐飲的資料都清空，避免下一筆訂單受前一筆訂單的影響 */
    refreshFoodOrder(state, refreshFoodOrder){                            
      state.foodOrder = refreshFoodOrder;
    },

    /* 更新與儲存餐飲訂單 */
    updateFoodOrder(state, userSelectFood){
      const foodIndex = state.foodOrder.findIndex((item) => {             /* 在state.foodOrder中尋找是否已存在該商品名稱 */
        return item.product === userSelectFood.product;
      });

      if(foodIndex !== -1){                                               /* 若商品已存在於state.foodOrder中，則更新該商品的數量  */
                                                     
        if(userSelectFood.num === 0){                                     /* 若商品的數量被改為0，則將該商品從state.foodOrder中移除 */
          state.foodOrder.splice(foodIndex, 1);
        }else{                                                             /* 若商品的數量被改為0以外的數量，則更新該商品的數量 */
          state.foodOrder[foodIndex].num = userSelectFood.num;
        }

      }else{                                                               /* 若商品尚未存在於state.foodOrder中，則將此商品資訊新增至state.foodOrder中  */
        state.foodOrder.push(userSelectFood);
      }
    },

    /* 儲存購物車總額 */
    updateTotalPrice(state, cartPrice){                                   
      state.totalPrice = cartPrice;
    },

    /* 將訂單儲存在vuex的payOnlineTemporaryOrder中(表示payOnline的暫存訂單，若之後線上付款成功，便會再將訂單儲存到vuex的orderConfirmed中) */
    updateTemporaryOrder(state, temporaryOrder){                        
      state.payOnlineTemporaryOrder.push(temporaryOrder);
    },

    /* 儲存訂單 */
    updateOrder(state, userOrder){                                        
      state.orderConfirmed.push(userOrder);
      localStorage.setItem("vuex", JSON.stringify({ orderConfirmed: state.orderConfirmed}));    /* 將orderConfirmed資料手動儲存至localStorage中 */
    },

    /* 更新電影院的座位狀態(當使用者訂購了某場次的座位，則之後在訂購時，該座位就不能夠再選取。) */
    updateSeatStatus(state, order){                                       
      const index = state.seatStatus.findIndex((info)=>{
        return info.title === order.movie;
      })
      if(index !== -1){                                   /* 若index值不等於-1，也就表示在state.seatStatus中已有該電影的資料 */

        if (!state.seatStatus[index].dateSessions) {      /* 若該電影的dateSessions資料不存在，那麼就建立一個空陣列 */
          state.seatStatus[index].dateSessions = [];
        }

        const result = state.seatStatus[index].dateSessions.findIndex((info)=>{   /* 在該電影的dateSessions中，尋找與使用者的選擇 相符的日期和場次，並將該index值儲存在result中 */
          return info.date === order.date && info.session === order.session;
        })
        
        if(result !== -1){                                                  /* 若index值不等於-1，也就表示在dateSessions中，已有和使用者選擇相符的日期和場次資料 */
          if (!state.seatStatus[index].dateSessions[result].soldSeat) {     /* 若該場次soldSeat尚無資料，則建立一個空陣列 */
            state.seatStatus[index].dateSessions[result].soldSeat = [];
          }
          state.seatStatus[index].dateSessions[result].soldSeat.push(...order.seat);    /* 將使用者選擇的座位儲存至該soldSeat陣列中 */
        } else{                                                              /* index值等於-1，表示在dateSessions中，沒有和使用者選擇相符的日期和場次資料。因此直接建立一筆新的物件資料(包含日期、場次、已售座位)，並儲存進state.seatStatus[index].dateSessions中。 */
          state.seatStatus[index].dateSessions.push({
            date: order.date, 
            session: order.session, 
            soldSeat: [...order.seat],
          });
        }
        
      } else{                                /* 若index值等於-1，也就表示在state.seatStatus沒有該電影的資料，則建立一筆新的物件資料(包含電影名稱和dateSessions資料)，並儲存進state.seatStatus中。*/ 
        state.seatStatus.push({
          title: order.movie,
          dateSessions: [{ date: order.date, session: order.session, soldSeat: [...order.seat] }]
        });
      }

      localStorage.setItem("vuex", JSON.stringify({ seatStatus: state.seatStatus}));    /* 將seatStatus資料手動儲存至localStorage中 */
    },
  },
  
  modules: {},
  
  /* 掛載插件 */
  plugins: [localStore.plugin],             
});


