<template>
    <div class="container">
        <div class="illustration container">
            <h3>請選擇 {{ totalTicketNum }} 張票券的位置 </h3>
            <label><input class="emptySeat form-check-input" type="radio" disabled>空位</label>
            <label><input class="soldOutSeat form-check-input" type="radio" disabled>已售出</label>
            <label><input class="selectedSeat form-check-input" type="radio" disabled checked>已選擇</label>
            <label><img class="disabledImg" src="assets/accessibility.png">輪椅席 (請至現場購買)</label>
            <p>SCREEN</p>
        </div>
        <div class="seatTable container">
            <table>
                <tbody>
                    <tr v-for="row in rowData" :key="row" :id="row">  
                        <td v-for="num in 12" 
                            :key="num" 
                            :id="row+'-'+num" 
                            :class="{ 
                                soldOut: soldOutSeatId.includes(row+'-'+num), 
                                selected: chosenSeat.includes(row+'-'+num)
                            }"          
                        >     <!-- :class="{ soldOut: true }"可以透過soldOut class來綁定style樣式。 -->
                            <label class="seatLabel">
                                <input 
                                    type="checkbox" 
                                    name="seatChosen" 
                                    :value="row+'-'+num"
                                    class="seatInput"
                                    @change="toggleSeatSelection(row+'-'+num)"      
                                    :disabled= "soldOutSeatId.includes(row+'-'+num)"
                                >       <!-- :disabled="true"則用來禁止點選該input框 -->
                                {{ row }}
                            </label>
                        </td>
                    </tr>
                </tbody>
            </table>
            <button type="button" class="nextBtn btn btn-primary" @click="selectFood">下一步</button>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';
export default {
    name: "BookSeat",
    data(){
        return{
            cinema: "",             /* 第幾廳 */
            rowData: [],            /* 影廳排數資料 */
            chosenSeat: [],         /* 使用者已選擇的座位ID*/
            chosenTicketNum: 0,     /* 使用者已選擇的座位數量*/
            soldOutSeatId: []       /* 已售出座位的ID */
        }
    },
    computed:{
        ...mapState([ "films", "selectMovie", "seatStatus", "selectDate", "selectSession", "totalTicketNum" ]),
    },
    methods:{
        /* 根據使用者所選的電影，確認其所在的廳院，以及該廳院的資料  */
        checkCinema(){                                                      
            this.cinema = this.films.find((film)=> film.chineseTitle === this.selectMovie)?.cinema || ""             /*  這個不是三元運算子，而是『可選鏈 ?.』 能夠安全地存取物件屬性，避免 undefined 或 null 所引發的錯誤。『可選鏈 ?.』精常與 || 一起搭配使用，以提供預設值。*/
            switch(this.cinema){
                case "第一廳":
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I"];
                    break;
                case "第二廳":
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L","M"];
                    break;
                case "第三廳":
                case "第四廳":
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K"];
                    break;
                case "第五廳":
                case "第六廳":
                case "第七廳":
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H"];
                    break;
                default:
                    this.rowData = [];
            }
        },
        
        /* 確認使用者所選的電影，其已售出座位狀況，以正確顯示出座位表 */
        checkSeats(){                                   
            const soldOutSeatDetail = this.seatStatus.find((status)=> status.title === this.selectMovie)?.dateSessions || [];
            this.soldOutSeatId = soldOutSeatDetail.find((detail)=> detail.date === this.selectDate && detail.session ===  this.selectSession)?.soldSeat || [];
        },

        /* 將使用者選擇的座位(傳入座位id)做判斷，並做後續處理(將該座位id 加入/移除chosenSeat) */
        toggleSeatSelection(chosenSeatId){                              
            const index = this.chosenSeat.indexOf(chosenSeatId);        /* 透過indexOf，確認data的chosenSeat中，是否有使用者點選的該座位id。 */
            if (index === -1){                                          /* 若index等於-1，表示在chosenSeat中沒有該座位id的資料，那麼就繼續做下一個判斷。 */
                if (this.chosenSeat.length < this.totalTicketNum){      /* 若已選擇的座位數量<應該選擇的座位數量，就將使用者所點選的座位的id新增至chosenSeat陣列中 */
                    this.chosenSeat.push(chosenSeatId);
                }else{
                    alert("您已選滿" + this.totalTicketNum + "個座位!");
                }
            }else{                                                       /* 若index不等於-1，表示在chosenSeat中已有該座位id的資料，那麼就將此座位id從selectedSeat陣列中移除，也就是取消該座位。 */
                this.chosenSeat.splice(index, 1);
            }
            this.chosenTicketNum = this.chosenSeat.length;              /* 計算使用者已選擇的座位數量 */
        },

        /* 將使用者所選擇的座位ID儲存至Vuex */
        handleChosenSeat(userChosenSeat){                               
            this.$store.commit("updateChosenSeat", userChosenSeat);
        },

        /* 若座位皆選擇好，則執行handleChosenSeat函式，並跳轉到下一頁(加購餐飲)。若少選座位，則跳出訊息 */
        selectFood(){                                                   
            if(this.totalTicketNum === this.chosenTicketNum){
                this.handleChosenSeat(this.chosenSeat);
                this.$router.push('/bookFood');
            }else{
                alert("請選擇"+this.totalTicketNum+"個位置!");
            }
        }     
    },
    mounted(){
        this.checkCinema();
    },
    watch:{
        seatStatus:{
            handler(){
                this.checkSeats();
            },
            immediate: true,
            deep: true
        }
    }
}
</script>

<style scoped>
.illustration{
    text-align: center;
    margin-bottom: 15px;
}
.illustration h3{
    margin: 30px auto 20px;
    font-weight: bold;
}
.illustration label{
    margin: 10px;
}
.emptySeat{
    background-color: white;
}
.soldOutSeat{
    background-color: rgb(202, 4, 4);
}
.disabledImg{
    width: 18px;
    height: 18px;
    border: solid 2px rgb(4,15,201); 
    border-radius: 5px;
}
.illustration p{
    width: 70%;
    border: solid 2px rgb(137, 134, 134);
    margin: auto;
    text-align: center;
}
.seatTable{
    text-align: center;
}
table{
    width: 100%;
    margin: 5px auto;
}
td{
    border: 2px solid rgb(140 140 140);
    display: inline-block;
    border-radius: 5px;
    width: 5%;
    padding: 5px 0px;
    margin: 5px;
    text-align: center;
}
.seatLabel{
    width: 100%;
}
.seatInput{
    display: none;
}
#F td{
    border: none;
    color: transparent;
    pointer-events: none;
    user-select: none;
}
#F-2, #F-3{
    background: url(../../../public/assets/accessibility.png) no-repeat center center/45%;
}
.selected{
    background-color: rgb(152,181,249);
}
.soldOut{
    pointer-events: none;       /* 禁止點擊 */
    background-color: rgb(209,136,124);
}
.nextBtn{
    display: block;
    width: 200px;
    margin: 30px auto;
}
@media screen and (max-width: 960px){
    .illustration h3{
        margin: 30px auto 10px;
    }
    .illustration label{
        margin: 5px;
    }
    td{
        display: inline-block;
        border-radius: 5px;
        width: 20px;
        height: 22px;
        padding: 0px;
        margin: 3px;
        text-align: center;
        font-size: 14px;
    }
    .nextBtn{
        display: block;
        width: 150px;
        margin: 15px auto;
    }
}
</style>