<template>
    <div>
        <nav class="breadCrumb" style="--bs-breadcrumb-divider: '>';" aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="#/">Home</a></li>
                <li class="breadcrumb-item"><a href="#/movie/">電影介紹</a></li>
                <li class="breadcrumb-item active" aria-current="page">{{ movieDetail.chineseTitle }}</li>
            </ol>
        </nav>
        <div class="movieInfo container">
            <img :src="movieDetail.src" :alt="movieDetail.alt" class="movieImg">
            <div class="movieDetail ">
                <div class="titleAndRating">
                    <h2 class="movieTitle">{{ movieDetail.chineseTitle }}</h2>
                    <img class="movieRating" :src="movieDetail.about.rating">
                </div>
                <h4 class="movieEngTitle">{{ movieDetail.title }}</h4>
                <hr>
                <h5 class="movieDetailH5">電影資訊 Movie Info</h5>
                <p>導演: {{ movieDetail.about.director }}</p>
                <p class="actor">演員(配音): {{ movieDetail.about.actors }}</p>
                <p>類型: {{ movieDetail.about.style }}</p>
                <p>片長: {{ movieDetail.about.time }}</p>
            </div>
        </div>
        <div class="movieStory container">
            <h5 class="movieDetailH5">劇情介紹 Story Introduction</h5>
            <hr>
            <p class="movieStoryWord">{{ movieDetail.about.story }}</p>
            <iframe :src="movieDetail.about.trailer" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';

export default {
    name:"MovieDetailView",
    data(){
        return{
            movieDetail: { about:{} },          /* 若只寫movieDetail:{}，這樣在模板中如movieDetail.about.level 這種「深層」存取會報錯。 */
        }                                       /* 因為about不存在 (undefined)，因此當Vue在存取undefined.level時，就會報錯。 */
    },                                          /* 而若寫成movieDetail = { about: {} }，能夠確保about一定存在，避免undefined錯誤。 */
    computed: {
        ...mapState([ 'films' ]),
    },
    methods:{
        /* 將電影詳細資訊儲存在movieDetail中 */
        generateMovieDetail(){
            this.movieDetail = this.films.find((m)=>{
                return m.id === this.$route.params.movieId;
            })
            /* console.log("電影完整資料:", this.movieDetail, "電影about資料:", this.movieDetail.about); */
        }
    },
    mounted(){
        this.generateMovieDetail();
        window.scrollTo(0, 0);         /* 手動將頁面滾動至頂部(因有些頁面打開時，會自動跳到最底部) */
    }
}
</script>

<style scoped>
.movieInfo{
    max-width: 1000px;
    margin: 35px auto; 
    display: flex;
}
.movieImg {
    width: 600px;
    object-fit: contain;
    border-radius: 5px;
}
.movieDetail{
    margin: 30px 50px;
    width: 500px;
    line-height: 1.8;
}
.titleAndRating{
    display: flex;
}
.movieRating{
    width: 50px;
    object-fit: contain;
    margin: 0px 0px 10px 10px;
    border-radius: 5px;
}
.movieTitle{
    font-weight: bold;
}
.movieEngTitle {
    color: rgb(38, 38, 241);
    font-weight: bold;
}
.movieDetailH5{
    color: rgb(102,43,43);
    font-size: 24px;
    font-weight: 550;
}
.movieStory{
    width: 100%;
    max-width: 1000px;
    margin: 50px auto;
}
.movieStoryWord{
    line-height: 1.8;
}
.movieStory iframe{
    display: block;
    width: 1000px;
    height: 500px;
    margin: 30px auto;
    padding: 15px;
    border-radius: 15px;
    background-color:  rgba(156, 71, 71, 0.872);
}
@media screen and (max-width: 960px){
    .movieInfo{
        display: block;
    }
    .movieImg {
        display: block;
        width: 90%;
        margin: 0px auto 25px;
    }
    .titleAndRating{
        display: flex;
        justify-content: center;
    }
    .movieEngTitle {
        color: rgb(38, 38, 241);
        font-weight: bold;
        text-align: center;
        width: 90%;
    }
    .movieDetailH5{
        font-size: 20px;
    }
    .movieDetail{
        margin: 0px;
        width: 100%;
    }
    .movieDetail p{
        font-size: 16px;
    }
    .movieStory iframe{
        width: 350px;
        height: 250px;
        padding: 10px;
        background-color:  rgba(156, 71, 71, 0.872);
    }
}
</style>