<template>
    <div class="container">
        <div class="creditCardImgDiv">
            <img src="assets/payment/mastercard.png" class="creditCard rounded" alt="mastercard圖示">
            <img src="assets/payment/visa.png" class="creditCard rounded" alt="visa圖示">
            <img src="assets/payment/jcb.png" class="creditCard rounded" alt="jcb圖示">
        </div>
        <div class="card container w-75 mb-3">
            <div class="receipt card-body">
                <h5 class="card-title">訂單編號: <span class="receiptNum">{{ $route.params.orderId }}</span> </h5>
                <h5 class="card-title">交易金額: <span class="price">{{ orderInfo.totalPrice }}</span>元 </h5>
                <form>
                    <div class="row mb-3">
                        <label for="cardHolder" class="col-sm-2 col-form-label">持卡人姓名</label>
                        <div class="col-sm-4">
                            <input v-model="cardHolder" type="text" id="cardHolder"
                                @input="isTyped.cardHolder = true" 
                                :class='["cardHolder", "form-control", {notice: isCardHolder}]' 
                            >
                        </div>
                        <div v-show="isCardHolder" class="noticeText"><p>*請輸入持卡人姓名(限字母)</p></div>
                    </div>
                    <div class="row mb-3">
                        <label for="cardNum1" class="col-sm-2 col-form-label">信用卡卡號</label>
                        <div class="cardNumber">
                            <div class="col-sm-2 cardNumDiv">
                                <input v-model="cardNum1" type="text" id="cardNum1"
                                    maxlength="4"
                                    @input="isTyped.cardNum1 = true" 
                                    :class='["cardNum", "form-control", {notice: isCardNum1}]' 
                                >
                            </div>
                            <div class="col-sm-2 cardNumDiv">
                                <input v-model="cardNum2" type="text" id="cardNum2"
                                    maxlength="4"
                                    @input="isTyped.cardNum2 = true" 
                                    :class='["cardNum", "form-control", {notice: isCardNum2}]' 
                                >
                            </div>
                            <div class="col-sm-2 cardNumDiv">
                                <input v-model="cardNum3" type="text" id="cardNum3"
                                    maxlength="4"
                                    @input="isTyped.cardNum3 = true" 
                                    :class='["cardNum", "form-control", {notice: isCardNum3}]' 
                                >
                            </div>
                            <div class="col-sm-2 cardNumDiv">
                                <input v-model="cardNum4" type="text" id="cardNum4"
                                    maxlength="4"
                                    @input="isTyped.cardNum4 = true" 
                                    :class='["cardNum", "form-control", {notice: isCardNum4}]' 
                                >
                            </div>
                        </div>
                        <div v-show="isCardNum1 || isCardNum2 || isCardNum3 || isCardNum4" class="noticeText">
                            <p>*請輸入信用卡卡號(每欄限4位數字)</p>
                        </div>
                    </div>
                    <div class="row mb-3">
                        <label for="expireYear" class="col-sm-2 col-form-label">信用卡到期日</label>
                        <div class="expireDate">
                            <div class="col-sm-2 expireDateInnerDiv">
                                <select v-model="cardYear" id="expireYear" aria-label=".form-select-md example"
                                    @click="isTyped.cardYear = true" 
                                    :class='["expireDateSelect form-select form-select-md mb-6", {notice: isCardYear}]' 
                                >
                                    <option v-for="year in Array.from({length: 11}, (_, i) => 2025 + i)" :key="year" :value="year">
                                        {{ year }}
                                    </option>
                                </select>
                            </div>
                            <label for="expireYear" class="col-sm-1 col-form-label">年</label>
                            <div class="col-sm-2 expireDateInnerDiv">
                                <select v-model="cardMonth" id="expireMonth" aria-label=".form-select-md example"
                                    @click="isTyped.cardMonth = true" 
                                    :class='["expireDateSelect form-select form-select-md mb-6", {notice: isCardMonth}]' 
                                >
                                    <option v-for="month in 12" :key="month" :value="month">{{ month }}</option>
                                </select>
                            </div>
                            <label for="expireMonth" class="col-sm-1 col-form-label">月</label>
                        </div>
                        <div v-show="isCardYear" class="noticeText"><p>*請輸入信用卡到期年</p></div>
                        <div v-show="isCardMonth" class="noticeText"><p>*請輸入信用卡到期月</p></div>
                    </div>
                    <div class="row mb-3">
                        <label for="checkCode" class="col-sm-2 col-form-label">信用卡檢查碼</label>
                        <div class="col-sm-2">
                            <input v-model="cardCheckCode" type="text" id="checkCode"
                                maxlength="3"
                                @input="isTyped.cardCheckCode = true" 
                                :class='["cardCheckCode", "form-control" ,{notice: isCardCheckCode}]' 
                            >
                        </div>
                        <div v-show="isCardCheckCode" class="noticeText"><p>*請輸入信用卡檢查碼(限3位數字)</p></div>
                    </div>
                    <button type="submit" class="btn btn-primary" @click="checkPayResult">確認送出</button>
                </form>
            </div>
        </div>
    </div>
</template>

<script>
import { mapState, mapMutations } from "vuex";

export default {
    name: "PayOnline",
    data(){
        return{
            orderInfo: {},
            cardHolder: "",
            cardNum1: "",
            cardNum2: "",
            cardNum3: "",
            cardNum4: "",
            cardYear: "",
            cardMonth: "",
            cardCheckCode: "",
            
            /* 判別使用者是否輸入過某欄位，不過並沒有檢查各欄位是否皆填寫完整 */
            isTyped:{               
                cardHolder: false,
                cardNum1: false,
                cardNum2: false,
                cardNum3: false,
                cardNum4: false,
                cardYear: false,
                cardMonth: false,
                cardCheckCode: false,
            }
        }
    },
    computed:{
        ...mapState([ "payOnlineTemporaryOrder" ]),
        isCardHolder(){
            return  this.isTyped.cardHolder && (this.cardHolder.length < 1 || !/^[a-zA-Z\s]+$/.test(this.cardHolder));       /* /^[a-zA-Z\s]+$/ 是正規表達達法，test()用來測試用 */
        },
        isCardNum1(){
            return this.isTyped.cardNum1 && !/^\d{4}$/.test(this.cardNum1);       /* /^\d{4}$/ 是正規表達法，指的是4 位數且只能是數字，test()用來測試用。而這邊在正規表達法前加了! 表示不是4 位數、不是數字 */
        },
        isCardNum2(){
            return this.isTyped.cardNum2 && !/^\d{4}$/.test(this.cardNum2);       
        },
        isCardNum3(){
            return this.isTyped.cardNum3 && !/^\d{4}$/.test(this.cardNum3);       
        },
        isCardNum4(){
            return this.isTyped.cardNum4 && !/^\d{4}$/.test(this.cardNum4);       
        },
        isCardYear(){
            return this.isTyped.cardYear && (this.cardYear === "" || this.cardYear === null) ;
        },
        isCardMonth(){
            return this.isTyped.cardMonth && (this.cardMonth === "" || this.cardMonth === null) ;
        },
        isCardCheckCode(){
            return this.isTyped.cardCheckCode && !/^\d{3}$/.test(this.cardCheckCode);       
        },
    },
    methods:{
        ...mapMutations([ "updateOrder", "updateSeatStatus"]),

        /* 透過訂單id，從vuex的payOnlineTemporaryOrder(儲存所有暫存訂單)，取得該筆訂單的其他資訊 */
        getOrderInfo(){
            const index = this.payOnlineTemporaryOrder.findIndex((order)=>{     
                return order.id === this.$route.params.orderId;
            });

            if(index !== -1){                                                   /* 不等於-1，表示在orderConfirmed中有找到該筆訂單 */
                this.orderInfo = this.payOnlineTemporaryOrder[index];           /* 將該筆訂單的資訊儲存在orderInfo中 */
            }
            else{                                                               /* 若找不到該筆訂單，則跳出提示訊息 */
                console.warn("找不到此筆訂單");
            }  
        },

        /* 避免使用者未填寫任何資料，就按下結帳按鈕 */
        /* (因為若在checkPayResult()中只寫checkReceiptDone()，在使用者完全沒有輸入過任何一欄位的情況下，isType為false，那麼就可以直接進入else條件式，表示結帳成功，這樣是有誤的，因此需再加上此isAllFilled()方法，確認每個欄位皆不是空的) */
        isAllFilled(){                  
            return (
                this.cardHolder.trim() !== "" &&        /* .trim()用來移除字串開頭與結尾的空白字元 */
                this.cardNum1.trim() !== "" &&          /* 所有欄位皆不是空字串，則回傳true */
                this.cardNum2.trim() !== "" &&
                this.cardNum3.trim() !== "" &&
                this.cardNum4.trim() !== "" &&
                this.cardYear !== "" &&
                this.cardMonth !== "" &&
                this.cardCheckCode.trim() !== ""
            );
        },

        /* 確認使用者各欄位皆填寫妥當 */
        checkReceiptDone(){             
            return this.isCardHolder ||
                this.isCardNum1 || 
                this.isCardNum2 || 
                this.isCardNum3 || 
                this.isCardNum4 || 
                this.isCardYear || 
                this.isCardMonth || 
                this.isCardCheckCode
        },

        /* 確認使用者各欄位都有填寫，且都有填寫妥當  */
        checkPayResult(event){
            event.preventDefault();                                     /* 防止表單提交，頁面直接刷新 */
            
            /* 若有未填寫或填寫不當的，會跳出提示訊息 */
            if(!this.isAllFilled() || this.checkReceiptDone())          /* 這邊!this.isAllFilled()表示false，也就是有欄位是空字串 */
            {
                alert("請確認信用卡資訊皆已填妥，謝謝!");  
            }else{
                this.orderInfo.isPaid = true;                            /* 將訂單中的isPaid(辨別是否已付款)改為true */
                this.updateOrder(this.orderInfo);                        /* 將訂單存至vuex */
                this.updateSeatStatus(this.orderInfo);                   /* 將使用者所選的座位存至vuex的seatStatus中 */
                this.$router.push(`/paySuccess/${this.$route.params.orderId}`);
            }
        }
    },
    mounted(){
        this.getOrderInfo();
    }
}
</script>

<style scoped>
.creditCardImgDiv{
    text-align: center;
}
.creditCard{
    width: 80px;
    height: 80px;
    object-fit: cover;
    margin: 10px;
}
.receiptNum{
    font-size: 16px;
}
.receipt{
    background-color: rgba(255, 254, 249, 0.281);
}
.price{
    color: red;
    font-weight: bold;
}
label{
    width: 120px;
}
.cardNumber, .expireDate{
    display: flex;
}
.cardNumDiv, .expireDateInnerDiv{
    width: 140px;
}
.cardNum{
    width: 130px;
}
.expireDateSelect{
    width: 130px;
}
.notice{
    border: 2px solid rgba(244, 169, 107, 0.831);
    box-shadow: 1px 1px 3px 1px   rgba(244, 169, 107, 0.518);
}
.noticeText{
    color: rgb(247, 10, 10);
}
@media screen and (max-width: 960px){
    .creditCard{
        width: 65px;
        height: 65px;
        object-fit: cover;
        margin: 10px;
    }
    .card{
        width: 95% !important;
    }
    .receipt{
        padding: 10px;
    }
    .cardHolder{
        width: 180px;
    }
    .cardNum{
        width: 65px;
        margin: 0px 2px;
    }
    .expireDateSelect{
        width: 90px;
        margin: 0px 3px;
    }
    .cardCheckCode{
        width: 80px;
    }
}
</style>