import { createRouter, createWebHashHistory } from "vue-router";
import HomeView from "../views/HomeView.vue";
import MovieView from "../views/MovieView.vue";
import MovieDetailView from "../views/MovieDetailView.vue";
import TheaterView from "../views/TheaterView.vue";
import FoodView from "../views/FoodView.vue";
import CartView from "../views/CartView.vue";
import SeatView from "../views/SeatView.vue";
import BookTicket from "../pages/bookTicket/BookTicket.vue";
import BookFood from "../pages/bookTicket/BookFood.vue";
import BookSeat from "../pages/bookTicket/BookSeat.vue";
import PayPage from "../pages/bookTicket/PayPage.vue";
import PayOnline from "../pages/bookTicket/PayOnline.vue";
import PayOnsite from "../pages/bookTicket/PayOnsite.vue";
import PaySuccess from "../pages/bookTicket/PaySuccess.vue";

const routes = [
  { path: "/", 
    component: HomeView,
    children:[
      { path: "seatview", component: SeatView }
    ]
  },
  { path: "/theater", component: TheaterView },
  { path: "/movie", component: MovieView,},
  { path: "/movie/:movieId", component: MovieDetailView },
  { path: "/food", component: FoodView },
  { path: "/cart", component: CartView },
  { path: "/bookTicket", component: BookTicket },
  { path: "/bookFood", component: BookFood },
  { path: "/bookSeat", component: BookSeat },
  { path: "/payPage", component: PayPage },
  { path: "/payOnline/:orderId", component: PayOnline },
  { path: "/payOnsite/:orderId", component: PayOnsite },
  { path: "/paySuccess/:orderId", component: PaySuccess},
];

export const router = createRouter({
  history: createWebHashHistory(),
  routes,
});