<template>
    <div class="container">
        <h3 class="foodH3">餐飲加購</h3>
        <div v-for="food in foods" :key="food.id" class="foodInfo container">
            <img :src="food.src" :alt= "food.product" class="foodImg">
            <div class="foodDetail">
                <div class="productAndPrice">
                    <h5>{{ food.product }}</h5>
                    <h6>${{ food.price }}</h6>
                </div>
                <p>{{ food.detail }}</p>
                <select class="foodSelect form-select form-select-sm" :id="food.id" @change="orderFood" aria-label="Small select example">
                    <option disabled>請選擇數量</option>
                    <option v-for="n in 6" :key="n-1" :value="n-1">{{ n-1 }}</option>
                </select>
                <button class="foodBtn btn btn-success" @click="handleFoodOrder(foodOrderList)">加入購物車</button>
            </div>
        </div>
        <button class= "nextBtn btn btn-primary" @click="checkCart">下一步</button>
    </div>
</template>

<script>
import { mapState, mapMutations } from 'vuex';

export default {
    name: "BookFood",
    data(){
        return{
            foodOrderList: {},      /* 使用者所選的餐飲和數量 */
        }
    },
    computed:{
        ...mapState([ "foods", "selectFood" ]),
   },
    methods:{
        ...mapMutations([ "refreshFoodOrder", "updateFoodOrder" ]),
        
        /* 將使用者所加購的餐飲存至foodOrderList物件 */
        orderFood(event){                                                   
            const productEngName = event.target.id;
            const productQuantity = Number(event.target.value);
            const productTWName = this.foods.find((item)=>{
                return item.id === productEngName }) ?.product || "";
            this.foodOrderList = {product: productTWName, num: productQuantity};         /* 當使用者改變了某餐飲項目的數量，將該項目的名稱和數量以物件的形式儲存在foodOrderList中 */     
        },

        /* 將使用者所選擇的餐飲及其數量，儲存至vuex，並跳出提示訊息 */
        handleFoodOrder(foodOrderList){                                
            if( this.foodOrderList.num > 0){
                this.$store.commit("updateFoodOrder", foodOrderList);                                       
                alert(this.foodOrderList.num + " 份 " + this.foodOrderList.product + " 已加入購物車 " );     
            }else if(this.foodOrderList.num === 0){                                                          
                this.$store.commit("updateFoodOrder", foodOrderList);
                alert(this.foodOrderList.product + " 已改為 "+ this.foodOrderList.num + " 份 ");
            }else{                                                      
                alert("請選擇數量後再加入購物車，謝謝");                   /* 當使用者直接按下加入購物車，而從未更改過數量時，跳出提示訊息。(此時因為沒有更改過數量，因此不會觸發orderFood函式，也因此foodOrderList還是一個空物件。) */
            }
            this.foodOrderList = {};                                    /* 經過條件判斷後，將this.foodOrderList重置成空物件。避免當某商品數量為0時，使用者按下加入購物車，跑出上一個加入購物車商品的資訊。 */
        },

         /* 跳轉至購物車頁面 */
        checkCart(){                                                   
            this.$router.push("/cart");
        }
   },
   /* 進入路由前(切換到此頁面前，且組件尚未創建)，將加購餐飲的資料都清空，避免下一筆訂單受前一筆訂單的影響。 */
   beforeRouteEnter(to, from, next){                
    next(vm => {
        vm.$store.commit("refreshFoodOrder", [] );

        vm.foodOrderList = {};
    })
   }
}
</script>

<style scoped>
    .foodH3{
        width: 80%;
        margin: 30px auto;
        font-weight: bold;
    }
    .foodInfo{
        width: 80%;
        margin: 30px auto;
        height: 300px;
        display: flex;
        background-color: rgba(193, 190, 190, 0.411);
        border-radius: 10px;
    }
    .foodImg{
        display: block;
        width: 45%;
        height: 80%;
        margin: auto;
        object-fit: cover;
        border-radius: 10px;
    }
    .foodDetail{
        width: 45%;
        margin: auto;
    }
    .productAndPrice{
        display: flex;
    }
    .foodDetail h5{
        font-weight: bold;
        font-size: 22px;
    }
    .foodDetail h6{
        font-weight: bold;
        font-size: 20px;
        margin-left: 15px;
    }
    .foodSelect{
        margin-bottom: 15px; 
    }
    .nextBtn{
        display: block;
        width: 200px;
        margin: 30px auto;
    }
    @media screen and (max-width: 960px){
        .foodH3{
            margin: 15px auto;
        }
        .foodInfo{
            width: 90%;
            height: 425px;
            margin: 30px auto;
            padding-top: 5px;
            display: block;
            background-color: rgba(193, 190, 190, 0.411);
            border-radius: 10px;
            box-shadow: 1px 1px 3px 3px rgba(128, 128, 128, 0.276) ;
        }
        .foodImg{
            display: block;
            width: 75%;
            height: 40%;
            margin: 10px auto;
            object-fit: cover;
            border-radius: 10px;
        }
        .productAndPrice{
            display: flex;
            justify-content: center;
        }
        .foodDetail{
            width: 90%;
            margin: auto;
        }
        .foodBtn{
            display: block;
            width: 150px;
            margin: 0px auto;
        }
    }
</style>