<template> 
    <div class="seatDiv container">
        <h4 class="seatH4"><span class="seatH4Span">【{{ selectMovie }}＊{{ selectDate }}＊{{ selectSession }}】</span> 座位表</h4>
        <div class="illustration">
            <label><input class="emptySeat form-check-input" type="radio" disabled>空位</label>
            <label><input class="soldOutSeat form-check-input" type="radio" disabled>已售出</label>
            <label><img class="disabledImg" src="assets/accessibility.png">輪椅席 (請至現場購買)</label>
            <p class="illustrationScreen">SCREEN</p>
        </div>
        <div class="seatTable container">
            <table>
                <tbody>
                    <tr v-for="row in rowData" :key="row" :id="row">  
                        <td v-for="num in 12" 
                            :key="num" 
                            :id="row+'-'+num" 
                            :class='["container", { soldOut: soldOutSeatId.includes(row+"-"+num) }]'
                        >
                            <label>
                                <input 
                                    type="checkbox" 
                                    name="seatChosen" 
                                    :value="row+'-'+num"
                                    class="seatInput"        
                                    :disabled= "soldOutSeatId.includes(row+'-'+num)"
                                >       <!-- :class="{ soldOut: true }" 透過soldOut的class來綁定style樣式。:disabled="true"則用來禁止點選該input框 -->
                                {{ row }}
                            </label>
                        </td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';
export default {
    name: "SeatView",
    data(){
        return{
            cinema: "",
            cinemaSeatNum: 0,
            rowData: [],
            soldOutSeatId: [],
        }
    },
    computed:{
        ...mapState([ "films", "selectMovie", "selectDate", "selectSession", "seatStatus" ]),
    },
    watch:{
        selectMovie:{
            handler(){
                this.generateCinema();         
            },
            immediate: true
        },
       selectSession:{
            handler(){
                this.checkSeats();
            },
            immediate: true,
            deep: true
        },
        seatStatus:{
            handler(){
                this.checkSeats();
            },
            immediate: true,
            deep: true
        }
    },
    methods:{
        /* 根據使用者所選的電影，確認其所在的廳院，以及該廳院的資料  */
        generateCinema(){
            this.cinema = this.films.find((film)=> film.chineseTitle === this.selectMovie)?.cinema || ""             /*  這個不是三元運算子，而是『可選鏈 ?.』 能夠安全地存取物件屬性，避免 undefined 或 null 所引發的錯誤。『可選鏈 ?.』精常與 || 一起搭配使用，以提供預設值。*/
            
            switch(this.cinema){
                case "第一廳":
                    this.cinemaSeatNum = 48
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I"];
                    break;
                case "第二廳":
                    this.cinemaSeatNum = 144;
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L","M"];
                    break;
                case "第三廳":
                case "第四廳":
                    this.cinemaSeatNum = 120;
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K"];
                    break;
                case "第五廳":
                case "第六廳": 
                case "第七廳":
                    this.cinemaSeatNum = 84;
                    this.rowData = ["A", "B", "C", "D", "E", "F", "G", "H"];
                    break;
                default:
                    this.cinemaSeatNum = 0;
                    this.rowData = [];
            }
        },

        /* 確認使用者所選的電影，其已售出座位狀況，以正確顯示出座位表 */
        checkSeats(){                                   
            const soldOutSeatDetail = this.seatStatus.find((status)=> status.title === this.selectMovie)?.dateSessions || [];
            this.soldOutSeatId = soldOutSeatDetail.find((detail)=> detail.date === this.selectDate && detail.session ===  this.selectSession)?.soldSeat || [];
        },          
    }
}
</script>

<style scoped>
.seatDiv{
    background-color: rgb(232,232,220);
    border-radius: 5px;
    padding: 0px;
}
.seatH4{
     width: 100%;
    padding: 10px 10px 10px 30px;
    background-color:rgba(187, 187, 185, 0.256);
    border-radius: 5px;
    font-weight: bold;
    text-align: center;
}
.seatH4Span{
    font-size: 20px;
}
.illustration{
    text-align: center;
}
.illustration label{
    margin: 3px 10px;
}
.emptySeat{
    background-color: white;
}
.soldOutSeat{
    background-color: rgb(202, 4, 4);
}
.disabledImg{
    width: 18px;
    height: 18px;
    border: solid 2px rgb(4,15,201); 
    border-radius: 5px;
}
.illustrationScreen{
    width: 65%;
    border: solid 2px rgb(137, 134, 134);
    margin: 10px auto;
    text-align: center;
}
.seatTable{
    text-align: center;
}
table{
    width: 100%;
    margin: 6px auto;
}
td{
    border: 2px solid rgb(140 140 140);
    display: inline-block;
    border-radius: 5px;
    width: 25px;
    height: 25px;
    padding: 0px;
    margin: 5px;
    text-align: center;
}
.seatInput{
    display: none;
}
#F td{
    border: none;
    color: transparent;
    pointer-events: none;
    user-select: none;
}
#F-2, #F-3{
    background: url(../../public/assets/accessibility.png) no-repeat center center/70%;
}
.soldOut{
    pointer-events: none;       /* 禁止點擊 */
    background-color: rgb(209,136,124);
}
@media screen and (max-width: 960px){
    .seatDiv{
        padding-bottom: 10px;
    }
    td{
        border: 2px solid rgb(140 140 140);
        display: inline-block;
        border-radius: 5px;
        width: 20px;
        height: 22px;
        padding: 0px;
        margin: 3px;
        text-align: center;
        font-size: 14px;
    }
}
</style>