<template>
    <div>
        <div class= "container">
            <div class="ticketDetailDiv container">
                <h5 class="bookTicketH5">目前選定的電影場次資訊如下:</h5>
                <ul class="ticketDetailUl">
                    <li> <span>電影:</span>     {{ selectMovie || "尚未選擇電影" }}</li>
                    <li> <span>日期:</span>     {{ selectDate || "尚未選擇日期" }} </li>
                    <li> <span>場次:</span>     {{ selectSession || "尚未選擇場次" }} </li>
                </ul>
            </div>
            <div class="ticketTypeDiv container">
                <h5 class="bookTicketH5">請選擇票種與數量</h5>
                <p>全票 (300元 / 張)
                    <select v-model="regularTicketNum" @change="handleRegularTicket(regularTicketNum)" class="ticketTypeSelect form-select form-select-sm" aria-label="Small select example">
                        <option disabled value="">請選擇全票數量</option>
                        <option v-for="n in 6" :key="n-1" :value="n-1">{{ n-1 }}</option>
                    </select>
                </p>
                <p>優待票 (260元 / 張)
                    <select v-model="concessionTicketNum" @change="handleConcessionTicket(concessionTicketNum)" class="ticketTypeSelect form-select form-select-sm" aria-label="Small select example">
                        <option disabled value="">請選擇優待票數量</option>
                        <option v-for="n in 6" :key="n-1" :value="n-1">{{ n-1 }}</option>
                    </select>
                </p>
                <div class="ticketTypeAlert alert alert-warning mt-3" role="alert">購買優待票者，敬請於取票當日，出示有效證件，謝謝您!</div>
                <button type="button" class="btn btn-primary" @click="selectSeat">繼續訂票</button>
            </div>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';

export default {
    name: "BookTicket",
    data(){
        return{
            regularTicketNum: 0,        /* 全票數量 */
            concessionTicketNum: 0,     /* 優待票數量 */
            totalTicketNum: 0,          /* 票數總和 */
        }
    },
    computed:{
        ...mapState([ "selectMovie", "selectDate", "selectSession" ])
    },
    methods:{
        /* 將使用者所選的全票數量存至Vuex，並計算總票數 */
        handleRegularTicket(userSelectRegularNum){                                      
            this.$store.commit("updateRegularTicketNum", userSelectRegularNum);
            this.totalTicketNum = this.regularTicketNum + this.concessionTicketNum;
        },

        /* 將使用者所選的優待票數量存至Vuex，並計算總票數 */
        handleConcessionTicket(userSelectConcessionNum){                                
            this.$store.commit("updateConcessionTicketNum", userSelectConcessionNum);
            this.totalTicketNum = this.regularTicketNum + this.concessionTicketNum;
        },

        /* 將使用者所選的總票數(全票+優待票)存至Vuex */
        handleTotalTicket(userSelectTicketNum){                                 
            this.$store.commit("updateTotalTicketNum", userSelectTicketNum);
        },

        /* 若使用者沒有選擇任何票(也就是全票數和優待票數皆=0)，則跳出提示訊息。否則就執行handleTotalTicket函式，並跳轉至下一頁(選擇座位)。 */
        selectSeat(){                                                           
            if(this.regularTicketNum === 0  && this.concessionTicketNum === 0){
                alert("請至少選擇一種票種的數量，謝謝!");
            }else{
                this.handleTotalTicket(this.totalTicketNum);
                this.$router.push('/bookSeat');
            } 
        },
    },
    /* 進入路由前，將資料都歸零，避免下一筆訂單受前一筆訂單的影響 */
    beforeRouteEnter(to, from, next){                               /* beforeRouteEnter表示進入路由前(切換到此頁面前，且組件尚未創建)執行。 */
        next(vm => {                                                /* 若數據存在Vuex中，且希望在進入頁面前清除Vuex的狀態，便可用beforeRouteEnter。 */
            vm.$store.commit("updateRegularTicketNum", 0);          /* next(vm => { ... })表示須執行完next()中的指令，否則頁面不會跳轉*/
            vm.$store.commit("updateConcessionTicketNum", 0);       /* 因為組件尚未建立，因此在beforeRouteEnter中無法使用this，需用next(vm => { ... })來存取Vue實例 */
            vm.$store.commit("updateTotalTicketNum", 0);

            vm.regularTicketNum = 0;                                      
            vm.concessionTicketNum = 0;
            vm.totalTicketNum = 0;
        })
    }
}
</script>

<style scoped>
.ticketDetailDiv{
    margin-top: 30px;
}
.bookTicketH5{
    font-weight: bold;
}
.ticketDetailUl li{
    font-size: 18px;
    list-style-type: circle;
}
.ticketDetailUl li span{
    font-weight: 400;
}
.ticketTypeDiv{
    margin-top: 50px;
}
.ticketTypeSelect{
    width: 600px;
}
.ticketTypeAlert{
    width: 600px;
}
@media screen and (max-width: 960px){
    .ticketTypeSelect{
        width: 75%;
    }
    .ticketTypeAlert{
        width: 75%;
    }
}
</style>
