<template>
    <div>
        <nav class="breadCrumb" style="--bs-breadcrumb-divider: '>';" aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="#/">Home</a></li>
                <li class="breadcrumb-item active" aria-current="page">電影介紹</li>
            </ol>
        </nav>
        <div class="movieInfo container">
