            <a :href="'#/movie/'+film.id" class="btn btn-primary" :id= "film.id" @click= "movieClick">
                <img :src="film.src" :alt="film.alt" class="movieImg card-img-top" :id= "film.id">
                <div class="movieDetail card-body" :id= "film.id">
                    <p class="movieFormat" :id= "film.id">{{ film.about.style }}</p>
                    <h5 class="movieTWTitle card-title" :id= "film.id">{{ film.chineseTitle }}</h5>
                    <p class="movieEngTitle card-text" :id= "film.id">{{ film.title }}</p>
                </div>
            </a>
            </div>
        </div>
    </div>
</template>

<script>
import { mapState } from 'vuex';

export default {
    name:"MovieView",
    data(){
        return{
            movieId: "",
        }
    },
    computed: {
        ...mapState([
            'films',
        ])
    },
    methods:{
        movieClick(event){
            this.movieId = event.target.id;
        }
    }
}
</script>

