<template>
    <div class= "container">
        <div class="row">
            <div class="col-sm-6 mb-3 mb-sm-0">
                <div class="card">
                <div class="card-body">
                    <img src="assets/payment/online.png" class="payImg" alt="線上付款圖示">
                    <h5 class="card-title"><strong>線上付款</strong></h5>
                    <p class="card-text">一般購票/銀行優惠</p>
                    <button class="btn btn-primary" @click="payOnline">下一步</button>
                </div>
                </div>
            </div>
            <div class="col-sm-6">
                <div class="card">
                <div class="card-body">
                    <img src="assets/payment/onsite.png" class="payImg" alt="現場付款圖示">
                    <h5 class="card-title"><strong>現場付款</strong></h5>
                    <p class="card-text">團體優待票/輪椅席</p>
                    <button class="btn btn-primary" @click="payOnsite">下一步</button>
                </div>
                </div>
            </div>
        </div>
        <div class="noticeMsg alert alert-warning" role="alert">
            <h5><strong>注意事項:</strong></h5>
            <p>1. 為了維護所有顧客線上訂票之權益，若有疑似惡意佔位或影響其他顧客之訂票者，本影城具有調整或取消訂位之最終權利，敬請見諒。</p>
            <p>2. 本影城<strong>不會</strong>請顧客至ATM操作解除分期或補繳費用，敬請您提高警覺，避免受騙。如有相關疑問，歡迎致電詢問。PREMIERE影城與您共同杜絕詐騙。</p>
        </div> 
    </div>
</template>

<script>
import { mapState, mapMutations } from 'vuex';
import { v4 as uuidv4 } from 'uuid';            /* 引入uuid套件，以產生唯一值的id作為訂單編號 */

export default {
    name: "PayPage",
    data(){
        return{
            order: {},
        }
    },
    computed:{
        ...mapState([ "selectMovie", "selectDate", "selectSession", "regularTicketNum", "concessionTicketNum", "totalTicketNum", "chosenSeat", "foodOrder", "totalPrice", "seatStatus", "orderConfirmed" ])
    },
    methods:{
        ...mapMutations([ "updateOrder", "updateSeatStatus", "updateTemporaryOrder"]),
        
        /* 建立訂單 */
        establishOrder(){                       
            this.order = {
                id: uuidv4(),                   /* 透過uuidv4()這個方法，可以產生唯一值的id作為訂單編號 */
                movie: this.selectMovie,
                date: this.selectDate,
                session: this.selectSession,
                regularTicket: this.regularTicketNum,
                concessionTicket: this.concessionTicketNum,
                totalTicket: this.totalTicketNum,
                totalPrice: this.totalPrice,
                seat: this.chosenSeat,
                food:  this.foodOrder,
                isPaid: false,
            }
        },

        /* 線上付款 */
        payOnline(){
            this.establishOrder();
            this.updateTemporaryOrder(this.order);               /* 將訂單存至vuex的payOnlineTemporaryOrder中 */
            this.$router.push(`/payOnline/${this.order.id}`);    /* 跳轉至線上付款頁面 */
        },

        /* 現場付款 */
        payOnsite(){
            this.establishOrder();
            this.updateOrder(this.order);                        /* 將訂單存至vuex */
            this.updateSeatStatus(this.order);                   /* 將使用者所選的座位存至vuex的seatStatus中 */
            this.$router.push(`/payOnsite/${this.order.id}`);    /* 跳轉至臨櫃付款頁面 */
        }
    }
}
</script>

<style scoped>
.card{
    margin: 15px;
}
.payImg{
    width: 35%;
    height: 20%;
    display: block;
    margin: 10px auto;
}
.card-body{
    width: 100%;
    height: 100%;
    text-align: center;
    background-color: rgba(216, 213, 213, 0.537);
}
.btn{
    width: 50%;
}
.noticeMsg{
    font-size: 16px;
}
</style>