<template>
    <div class="container paySuccess">
        <h3><strong>訂單資訊</strong></h3>
        <hr>
        <h5>訂單編號:  {{$route.params.orderId }} <strong>(付款成功)</strong></h5>
        <hr>
        <div class="card" style="width: 20rem;">
            <img :src="getQRCode" class="card-img-top" alt="訂單QRcode">
            <div class="card-body">
                <table>
                    <tbody>
                        <tr> <th scope="row"></th> <td>★<strong>付款成功，訂單已成立★</strong></td> </tr>
                        <tr> <th scope="row">電影</th> <td>{{ orderInfo.movie }}</td> </tr>
                        <tr> <th scope="row">日期</th> <td>{{ orderInfo.date }}</td> </tr>
                        <tr> <th scope="row">場次</th> <td>{{ orderInfo.session }}</td> </tr>
                        <tr> <th scope="row">票券</th> <td>共{{ orderInfo.totalTicket }}張 (全票{{ orderInfo.regularTicket }}張 & 優待票{{ orderInfo.concessionTicket }}張)</td> </tr>
                        <tr> <th scope="row">座位</th> <td><span v-for="(seat, index) in orderSeat" :key="index">{{ seat }}</span></td> </tr>
                        <tr> <th scope="row">金額</th> <td>${{ orderInfo.totalPrice }}</td> </tr>
                        <tr> <th scope="row">餐飲</th> <td><span v-for="(food, index) in orderFood" :key="index">{{ food }}</span></td> </tr>
                        
                    </tbody>
                </table>
                <h6>感謝您的訂購，敬請截圖或記下訂單編號。並於{{ orderInfo.date }}觀影當天提早至現場領取票券以及兌換餐飲。<br>PREMIERE CINEMA祝您觀影愉快!</h6>
            </div>
        </div>
    </div>
</template>

<script>
import { mapState } from "vuex";

export default {
    name: "PaySuccess",
    data(){
        return{
            QRCode: "",
            orderInfo: {},
            orderFood: [],
            orderSeat: [],
        }
    },
    computed:{
        ...mapState([ "orderConfirmed" ]),

        /* 取得訂單id */
        getId(){                                                                
            return this.$route.params.orderId;                                  
        },

        /* 取得訂單網址 */
        getURL(){                                                               /* 網址若使用localhost，則只有自己的電腦能運行，到其他裝置上就會無法順利運作 */
            return `https://yt1368.github.io/cinema/#/paySuccess/${this.getId}` /* 若使用GitHub Pages的網址，就能夠確保QR Code指向正確的網站，且順利運行 */
        }, 
        
        /* 生成QR-Code */
        getQRCode(){                                                            
            return `https://quickchart.io/qr?text=${encodeURIComponent(this.getURL)}&size=200`
        }                                                                       /* 加上encodeURIComponent()，是為了確保URL正確編碼，避免 # 和 / 等符號被錯誤解析。加上encodeURIComponent()後，#會轉成%23。這樣就可以避免網址解析錯誤，以致掃描QR-Code，無法跳轉到正確的頁面。*/        
    },                                                                  
     methods:{
        /* 透過訂單id，從vuex的orderConfirmed(儲存所有訂單)中，取得該筆訂單的其他資訊 */
        getOrderInfo(){
            const index = this.orderConfirmed.findIndex((order)=>{              
                return order.id === this.getId;
            });
            if(index !== -1){                                                   /* 不等於-1，表示在orderConfirmed中有找到該筆訂單 */
                this.orderInfo = this.orderConfirmed[index];                    /* 將該筆訂單的資訊儲存在orderInfo中 */
                this.orderFood = this.orderInfo.food.map((item)=>{              /* 為方便餐飲和座位等資訊在模板上渲染，因此這邊先做加工(以join，替資料間加上頓號) */
                    return `${item.product} * ${item.num}`
                }).join("、");
                this.orderSeat = this.orderInfo.seat.join("、");
            }else{                                                               /* 若找不到該筆訂單，則跳出提示訊息 */
                console.warn("找不到此筆訂單");
            }  
        }
    },
    mounted(){
        this.getOrderInfo();
    },
    watch:{
        "$route.params.orderId": {
            handler(){
                this.getOrderInfo();
            },
            immediate: true,         
        }
    }
}
</script>

<style scoped>
.paySuccess{
    margin-bottom: 20px;
}
h3{
    width: 120px;
    margin: 20px auto 0px;
}
h5{
    max-width: 600px;
    margin: 0px auto;
    text-align: center;
}
.card{
    margin: 0px auto;
}
img{
    padding: 15px;
    background-color: rgba(184, 181, 181, 0.589);
}
table{
    font-size: 16px;
}
th{
    width: 40px; 
}
td{
    padding-left: 10px;
}
h6{
    background-color: rgba(250, 242, 158, 0.658);
    margin-top: 10px;
    padding: 10px;
    line-height: 1.5;
    letter-spacing: .5px;   /* 控制字元間的距離 */
}
</style>