<template>
    <div class="container">
        <h3><strong>請確認以下資訊，再按下一步</strong></h3>
        <div class="accordion" id="accordionExample">
            <div class="accordion-item">
                <h2 class="accordion-header">
                <button class="accordion-button" type="button" data-bs-toggle="collapse" data-bs-target="#collapseOne" aria-expanded="true" aria-controls="collapseOne">
                    <strong>票券資訊</strong>
                </button>
                </h2>
                <div id="collapseOne" class="accordion-collapse collapse show" data-bs-parent="#accordionExample">
                    <div class="accordion-body">
                        <table class="ticketDetail">
                            <tbody>
                                <tr><td><strong>電影:</strong></td> <td> {{ selectMovie }} </td></tr>
                                <tr><td><strong>日期:</strong></td> <td> {{ selectDate }} </td></tr>
                                <tr><td><strong>場次:</strong></td> <td> {{ selectSession }} </td></tr>
                                <tr><td><strong>全票:</strong></td> <td> {{ regularTicketNum }} 張 </td></tr>
                                <tr><td><strong>優待票:</strong></td> <td> {{ concessionTicketNum }} 張 </td></tr>
                                <tr><td><strong>座位:</strong></td> <td><span v-for="seat in chosenSeat.join('、')" :key="seat"> {{ seat }} </span></td> </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
            <div class="accordion-item">
                <h2 class="accordion-header">
                <button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#collapseTwo" aria-expanded="false" aria-controls="collapseTwo">
                    <strong>餐飲加購資訊</strong>
                </button>
                </h2>
                <div id="collapseTwo" class="accordion-collapse collapse" data-bs-parent="#accordionExample">
                    <div class="accordion-body">
                        <div class="foodDescription" v-for="food in foodOrderDetail" :key="food.product">
                            <img class="foodImg" :src="food.src" alt="餐飲圖片">
                            <div class="foodWordDesciption">
                                <h5 class="productAndPrice">{{ food.product }}   ${{ food.price }}</h5>
                                <div class="foodNumSelect">
                                    <select class="foodSelect form-select" :value="food.num" :id="food.product" @change="handleFoodNum" aria-label="Default select example">
                                        <option selected>請選擇數量</option>
                                        <option value="0">0</option>
                                        <option value="1">1</option>
                                        <option value="2">2</option>
                                        <option value="3">3</option>
                                        <option value="4">4</option>
                                        <option value="5">5</option>
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="accordion-item">
                <h2 class="accordion-header">
                <button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#collapseThree" aria-expanded="false" aria-controls="collapseThree">
                    <strong>總金額</strong>
                </button>
                </h2>
                <div id="collapseThree" class="accordion-collapse collapse" data-bs-parent="#accordionExample">
                    <div class="accordion-body totalPrice">
                        <table>
                            <tbody>
                                <tr> <td><strong>全票:</strong></td> <td>{{ regularTicketNum }}張，共 {{ regularTicketPrice }}元</td> </tr>
                                <tr> <td><strong>優待票:</strong></td> <td>{{ concessionTicketNum }}張，共 {{concessionTicketPrice}}元</td> </tr>
                                <tr> <td><strong>餐飲加購:</strong></td> <td>{{ foodTotalPrice }}元</td> </tr>
                            </tbody>
                        </table>
                        <hr>
                        <p><strong>共: {{ totalPrice }}元</strong></p>
                    </div>
                </div>
            </div>
        </div> 
        <button type="button" class="nextBtn btn btn-primary" @click="goPay">下一步</button>
    </div>
</template>

<script>
import { mapState, mapMutations } from 'vuex';

export default {
    name: "CartView",
    data(){
        return{
            foodOrderDetail: [],
            foodTotalPrice: 0,
        }
    },
    computed:{
        ...mapState([ "selectMovie", "selectDate", "selectSession", "regularTicketNum", "concessionTicketNum" , "chosenSeat", "foodOrder", "foods" ]),
        
        /* 計算全票總額 */
        regularTicketPrice(){                       
            return this.regularTicketNum * 300;
        },

        /* 計算優待票總額 */
        concessionTicketPrice(){                    
            return this.concessionTicketNum *260;
        },

        /* 計算購物車總額(票價+餐飲費) */
        totalPrice(){                               
            return this.regularTicketPrice + this.concessionTicketPrice + this.foodTotalPrice;
        }
    },
    methods:{
        ...mapMutations([ "updateFoodOrder", "updateTotalPrice" ]),

        /* 生成購物車中餐飲的資訊(商品名、圖片、數量、價格、總額)(此頁面mounted、當使用者在購物車修改餐飲數量後，皆會執行此函式。) */
        checkFoodDetail(){                          
           if(this.foodOrder.length === 0){
            this.foodOrderDetail = [];
           }
           this.foodOrderDetail = this.foodOrder.map((order)=>{                                     /* foodOrderDetail會取得使用者選購的餐飲，其相關資訊。方便後續在模板中渲染。 */
                const matchOrder = this.foods.find((item)=> item.product === order.product);        /* 比對foods餐飲總覽，並取得某餐飲的相關資訊 */
                return matchOrder? ({product: order.product, src: matchOrder.src, num: order.num, price: matchOrder.price, sum: order.num * matchOrder.price}) : null;
           })
           this.foodOrderDetail = this.foodOrderDetail.filter((item)=>{                             /* 過濾掉數量為0的餐飲 */
                return item !== null && item.num > 0;
           })
        },

        /* 計算購物車中餐飲的總價 */
        calculateFoodTotalPrice(){                                              
            this.foodTotalPrice = 0;
            this.foodOrderDetail.forEach((item)=>{
                this.foodTotalPrice += item.sum;
            })
        },

        /* 購物車中，使用者修改餐飲數量 */
        handleFoodNum(event){                                                   
            const productName = event.target.id;
            const productNewNum = Number(event.target.value);
            const newFoodOrder = { product: productName, num: productNewNum};
            this.$store.commit("updateFoodOrder", newFoodOrder);                /* 將修改的餐飲數量存至vuex */
            this.checkFoodDetail();                                             /* 再重新生成購物車中餐飲的資訊 */
        },

        /* 將購物車總額存至vuex，並跳轉至付款頁面*/
        goPay(){                                                                
            this.$store.commit("updateTotalPrice", this.totalPrice);            
            this.$router.push('/payPage');                                     
        }
    },
    watch:{
        foodOrderDetail:{
            handler(){
                this.calculateFoodTotalPrice();
            },
            immediate: true,
            deep: true,
        }
    },
    mounted(){
        this.checkFoodDetail();
    }
}
</script>

<style scoped>
h3{
    margin: 30px 0px 20px ;
}
.accordion-button{
    font-size: 20px;
}
.ticketDetail, .totalPrice{
    font-size: 18px;
}
.foodDescription{
    display: flex;
    height:250px;
    background-color: rgba(248, 234, 234, 0.461);
    border-radius: 10px;
    margin-bottom: 10px;
    box-shadow: 1px 1px 3px 3px rgba(128, 128, 128, 0.107) ;
}
.foodImg{
    display: block;
    width: 35%;
    height: 85%;
    margin: auto;
    object-fit: cover;
    border-radius: 10px;
}
.foodWordDesciption{
    width: 40%;
    height: 80%;
    margin: 60px auto;
}
.nextBtn{
    display: block;
    width: 200px;
    margin: 30px auto;
}
@media screen and (max-width: 960px){
    .foodDescription{
        height: 200px;
    }
    .foodImg{
        display: block;
        width: 45%;
        height: 70%;
        margin: auto;
        object-fit: cover;
        border-radius: 10px;
    }
}
</style>